import unittest
from ledger_csv import parse_rows

class LedgerRows(unittest.TestCase):
    def test_numeric_and_quoted_fields(self):
        rows = parse_rows('18,"018",2.75\n-4,"bay, east",0\n')
        self.assertEqual(rows, [[18.0, '018', 2.75], [-4.0, 'bay, east', 0.0]])
        self.assertIs(type(rows[0][0]), float)
        self.assertIs(type(rows[1][2]), float)
        self.assertIs(type(rows[0][1]), str)

    def test_escaped_quote_and_embedded_newline(self):
        self.assertEqual(parse_rows('"bay ""C""",8\n'), [['bay "C"', 8.0]])
        self.assertEqual(parse_rows('"north\nsouth",9\n'), [['north\nsouth', 9.0]])

    def test_empty_document(self):
        self.assertEqual(parse_rows(''), [])

    def test_empty_fields_and_invalid_unquoted_text(self):
        self.assertEqual(parse_rows(',2,""\n'), [['', 2.0, '']])
        with self.assertRaises(ValueError):
            parse_rows('dock,2\n')

if __name__ == '__main__':
    unittest.main()

